// Official DGT speed cameras (data/radars.json, generated by scripts/update-dgt-data.ts)
// and their position along a route.
import { CalculatedRoute } from './routing';
import { RouteIndex, buildRouteIndex, projectOnRoute, distanceToPolyline } from './geometry';
import { fetchWithTimeout } from './routing';

export interface Radar {
  id: string;
  type: 'fijo' | 'tramo';
  road: string;
  km: number | null;
  lat: number;
  lng: number;
  endLat?: number;
  endLng?: number;
  endKm?: number | null;
}

export interface RadarsResponse {
  success: boolean;
  source: string;
  updatedAt: string | null;
  radars: Radar[];
}

export interface RouteRadar {
  radar: Radar;
  // Distance from the route start to the camera (or to the start of the section)
  alongMeters: number;
  // Average-speed sections: distance to the end of the section
  endAlongMeters?: number;
}

export const RADARS_URL = `${import.meta.env.BASE_URL}data/radars.json`;

export async function loadRadars(): Promise<Radar[]> {
  try {
    const res = await fetchWithTimeout(RADARS_URL, 15000);
    if (!res.ok) return [];
    const data: RadarsResponse = await res.json();
    return Array.isArray(data.radars) ? data.radars : [];
  } catch {
    return [];
  }
}

// A camera belongs to the route when it is on the road the route uses. Cabin coordinates
// are on the hard shoulder, so a few tens of meters of tolerance are needed.
const ON_ROUTE_METERS = 45;

const normRoad = (s: string) => s.toUpperCase().replace(/[^A-Z0-9]/g, '');

// With turn-by-turn steps we also require that the route really uses the camera's road
// (OSRM gives the road number in `ref`, e.g. "A-70"): a cabin on a motorway must not
// warn a driver on a side street or a roundabout a few meters away.
export function routeUsesRoad(route: Partial<Pick<CalculatedRoute, 'steps'>>, roadNumber: string, lat: number, lng: number): boolean {
  if (!route.steps || route.steps.length === 0) return true;
  const road = normRoad(roadNumber);
  if (!road) return true;
  return route.steps.some((step) => {
    const refs = `${step.ref || ''};${step.name || ''}`.split(/[;,/]/).map(normRoad);
    return refs.includes(road) && step.geometry.length >= 2 && distanceToPolyline(lat, lng, step.geometry) <= ON_ROUTE_METERS * 2;
  });
}

export function radarsAlongRoute(route: Pick<CalculatedRoute, 'coordinates' | 'isApproximate'> & Partial<Pick<CalculatedRoute, 'steps'>>, radars: Radar[], index?: RouteIndex): RouteRadar[] {
  if (route.isApproximate || route.coordinates.length < 2 || radars.length === 0) return [];
  const idx = index || buildRouteIndex(route.coordinates);
  const result: RouteRadar[] = [];
  for (const radar of radars) {
    const start = projectOnRoute(idx, radar.lat, radar.lng);
    if (start.offsetMeters > ON_ROUTE_METERS) continue;
    if (!routeUsesRoad(route, radar.road, radar.lat, radar.lng)) continue;
    if (radar.type === 'tramo' && radar.endLat !== undefined && radar.endLng !== undefined) {
      const end = projectOnRoute(idx, radar.endLat, radar.endLng);
      // The section counts only if the route also reaches its end, after its start
      if (end.offsetMeters > ON_ROUTE_METERS || end.alongMeters <= start.alongMeters) continue;
      result.push({ radar, alongMeters: start.alongMeters, endAlongMeters: end.alongMeters });
    } else {
      result.push({ radar, alongMeters: start.alongMeters });
    }
  }
  return result.sort((a, b) => a.alongMeters - b.alongMeters);
}

export function describeRadar(radar: Radar): string {
  const km = radar.km !== null ? ` km ${String(radar.km).replace('.', ',')}` : '';
  return radar.type === 'tramo' ? `Tramo de velocidad media · ${radar.road}${km}` : `Radar fijo · ${radar.road}${km}`;
}
